def range_sums(values, queries):
    prefix = [0]
    for value in values:
        prefix.append(prefix[-1] + value)
    return [prefix[right] - prefix[left] for left, right in queries]

def warmer_days(temperatures):
    waits = [0] * len(temperatures)
    pending = []
    for i, temperature in enumerate(temperatures):
        while pending and temperatures[pending[-1]] < temperature:
            previous = pending.pop()
            waits[previous] = i - previous
        pending.append(i)
    return waits

def lower_bound(items, target):
    left, right = 0, len(items)
    while left < right:
        middle = (left + right) // 2
        if items[middle] < target:
            left = middle + 1
        else:
            right = middle
    return left

def task_order(graph):
    from collections import deque
    degree = dict.fromkeys(graph, 0)
    for neighbours in graph.values():
        for node in neighbours:
            degree[node] += 1
    ready = deque(node for node in graph if degree[node] == 0)
    result = []
    while ready:
        node = ready.popleft()
        result.append(node)
        for other in graph[node]:
            degree[other] -= 1
            if degree[other] == 0:
                ready.append(other)
    return result if len(result) == len(graph) else None

def distance(a, b):
    previous = list(range(len(b) + 1))
    for i, left in enumerate(a, 1):
        current = [i]
        for j, right in enumerate(b, 1):
            current.append(min(previous[j] + 1, current[-1] + 1,
                               previous[j - 1] + (left != right)))
        previous = current
    return previous[-1]

def pack(items, capacity):
    best = [0] * (capacity + 1)
    for weight, value in items:
        for room in range(capacity, weight - 1, -1):
            best[room] = max(best[room], best[room - weight] + value)
    return best[capacity]

def merge_sorted(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    return result + left[i:] + right[j:]
